public class ShieldEntity { private String id; private String characterId; private String name; private String description; private int hitPoints; private String imageUrl; protected ShieldEntity(){} public ShieldEntity(String id,String c,String n,String d,int p,String i){this.id=id;characterId=c;name=n;description=d;hitPoints=p;imageUrl=i;} public String getId(){return id;} public String getCharacterId(){return characterId;} public String getName(){return name;} public void setName(String v){name=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public int getHitPoints(){return hitPoints;} public void setHitPoints(int v){hitPoints=v;} public String getImageUrl(){return imageUrl;} public void setImageUrl(String v){imageUrl=v;} }
